#!/usr/bin/env node
/**
 * noindex-untranslated-vocab.cjs — mark the word-bank pages that are still
 * predominantly English as `noindex, follow`.
 *
 *   node scripts/noindex-untranslated-vocab.cjs          # apply
 *   node scripts/noindex-untranslated-vocab.cjs --check  # report, exit 1 on drift
 *   node scripts/noindex-untranslated-vocab.cjs --lift <locale>   # remove again
 *
 * WHY THESE PAGES, AND WHY NOINDEX RATHER THAN TRANSLATION.
 *
 * learn/<loc>/{vocabulary,vocabulary-browser,flashcard}.html each embed the
 * SAME static word-bank reference, generated by scripts/gen-lesson-static.cjs
 * from the 22 learn/data/vocabulary-*.json files. That generator resolves
 * `<field>_<locale>` and falls back to the English field when it is absent.
 *
 * Measured 2026-07-21 (`node scripts/audit-learn-locale-dup.cjs`): of the 447
 * translatable title/body/tip/meaning fields in those JSON files,
 *
 *     es: 0 missing      zh_tw: 42 missing     ja: 99 missing
 *     de / fr / vi / th / id: 447 missing — i.e. ALL of them
 *
 * So for those five locales the entire static reference renders in English:
 * ~17,500 duplicated characters per page, 96%+ of the page's sentence-length
 * prose byte-identical to learn/vocabulary.html. Fifteen URLs claiming, via
 * <html lang> and hreflang, to be translations of a page they simply copy.
 * That is the exact duplicate-content + misrepresentation profile that the
 * AdSense "Low value content" rejection cited.
 *
 * The honest fix is to translate the word bank in learn/data/vocabulary-*.json
 * (adding meaning_de, meaning_fr, meaning_vi, meaning_th, meaning_id, and the
 * matching title_/body_/tip_ fields) and rerun gen-lesson-static.cjs. That is
 * 2,235 field translations and was out of scope for this pass. Rather than
 * ship a machine gloss or leave the duplicates indexed, these 15 URLs are
 * noindexed until the JSON is done.
 *
 * The pages remain fully usable — their interactive UI is translated through
 * js/langs/lang-<code>.js. Only the crawler is told not to index them.
 * `follow` is kept so link equity still flows to the lessons they link to.
 *
 * TO LIFT: translate the JSON, rerun gen-lesson-static.cjs, confirm with
 * audit-learn-locale-dup.cjs that sentenceRatio is near 0, then run with
 * --lift <locale>. Do not lift without re-measuring.
 *
 * ── 2026-07-26: THE GATE NO LONGER FIRES ────────────────────────────────
 * The word bank has since been translated. Re-measured 2026-07-26 during the
 * Phase-A translation triage (docs/writing-typing/qa-triage-results.md), over
 * the 448 translatable title/body/meaning/tip fields in learn/data/
 * vocabulary-*.json:
 *
 *     title/body/meaning — 0 missing in ALL 8 locales (was 447 for five)
 *     tip.label/tip.text — 0 missing for ja/zh_tw/es; 42 for de/fr/vi/th/id,
 *                          since translated (see qa-vocab-tips.workflow.js)
 *
 * The script used to ASSERT the 2026-07-21 measurement rather than take one,
 * so `--check` still reported all 15 pages as DRIFT and a plain run would
 * have re-noindexed 15 pages whose prose is now translated. It now measures
 * coverage itself.
 *
 * The threshold matters as much as the measurement. This gate exists for the
 * case it was written for — a page whose static reference renders
 * PREDOMINANTLY in English (it was 96%+ of sentence-length prose). A small
 * residue is a translation backlog, not a duplicate-content page, and
 * noindexing 15 URLs over it would cost more than it saves. So the gate fires
 * only above MIN_UNTRANSLATED_RATIO; anything below is reported and left
 * indexed. The gate stays in the repo because it is still the correct
 * response if coverage ever regresses that far.
 *
 * Idempotent. Preserves each file's original line endings.
 */

'use strict';
const fs = require('fs');
const path = require('path');

const ROOT = path.resolve(__dirname, '..');
const LOCALES = ['de', 'fr', 'vi', 'th', 'id'];
const PAGES = ['vocabulary.html', 'vocabulary-browser.html', 'flashcard.html'];

const MARKER = '<!-- noindex: untranslated word bank — see scripts/noindex-untranslated-vocab.cjs -->';
const TAG = '<meta name="robots" content="noindex, follow">';

const CHECK = process.argv.includes('--check');
const liftIdx = process.argv.indexOf('--lift');
const LIFT = liftIdx !== -1 ? process.argv[liftIdx + 1] : null;

function readLF(abs) {
  const raw = fs.readFileSync(abs, 'utf8');
  const crlf = raw.includes('\r\n');
  return { text: crlf ? raw.replace(/\r\n/g, '\n') : raw, crlf };
}
function writeLF(abs, text, crlf) {
  fs.writeFileSync(abs, crlf ? text.replace(/\n/g, '\r\n') : text, 'utf8');
}

/* ── measure, don't assume ───────────────────────────────────────────────
   Count the translatable word-bank fields that lack a `_<locale>` sibling.
   A locale with zero missing is fully translated and must NOT be noindexed,
   whatever this file's header used to claim. */
const BASE_FIELDS = ['title', 'body', 'meaning'];
const TIP_SUBFIELDS = ['label', 'text'];

/* Fire only when the embedded reference is predominantly English — the
   condition this gate was written for. See the header. */
const MIN_UNTRANSLATED_RATIO = 0.5;

function wordBankGaps(locale) {
  const suf = locale.replace('-', '_');
  const dir = path.join(ROOT, 'learn', 'data');
  let total = 0, missing = 0;
  fs.readdirSync(dir)
    .filter(n => /^vocabulary-.*\.json$/.test(n))
    .forEach(name => {
      const json = JSON.parse(fs.readFileSync(path.join(dir, name), 'utf8'));
      (function walk(node) {
        if (Array.isArray(node)) return node.forEach(walk);
        if (!node || typeof node !== 'object') return;
        BASE_FIELDS.forEach(f => {
          if (typeof node[f] !== 'string' || !node[f].trim()) return;
          total++;
          const v = node[f + '_' + suf];
          if (typeof v !== 'string' || !v.trim()) missing++;
        });
        if (node.tip && typeof node.tip === 'object') {
          TIP_SUBFIELDS.forEach(sub => {
            if (typeof node.tip[sub] !== 'string' || !node.tip[sub].trim()) return;
            total++;
            const t = node['tip_' + suf];
            const v = t && typeof t === 'object' ? t[sub] : null;
            if (typeof v !== 'string' || !v.trim()) missing++;
          });
        }
        Object.values(node).forEach(v => { if (v && typeof v === 'object') walk(v); });
      })(json);
    });
  return { total, missing };
}

let changed = 0, drift = 0, already = 0, skipped = 0;
const targets = LIFT ? [LIFT] : LOCALES;

for (const loc of targets) {
  if (!LIFT) {
    const { total, missing } = wordBankGaps(loc);
    const ratio = total ? missing / total : 0;
    if (ratio < MIN_UNTRANSLATED_RATIO) {
      skipped++;
      console.log(`  SKIP ${loc} — ${missing}/${total} fields untranslated ` +
        `(${(ratio * 100).toFixed(1)}%, under the ${MIN_UNTRANSLATED_RATIO * 100}% gate); ` +
        `noindex would be wrong${missing ? ' — translate the residue instead' : ''}`);
      continue;
    }
    console.log(`  ${loc}: ${missing}/${total} word-bank fields untranslated ` +
      `(${(ratio * 100).toFixed(1)}%) → gate applies`);
  }
  for (const page of PAGES) {
    const rel = path.join('learn', loc, page);
    const abs = path.join(ROOT, rel);
    if (!fs.existsSync(abs)) { console.warn(`  missing ${rel}`); continue; }

    const { text, crlf } = readLF(abs);
    const has = text.includes(MARKER);
    let out = text;

    if (LIFT) {
      if (!has) continue;
      out = text.replace(new RegExp(`[ \\t]*${MARKER}\\n[ \\t]*${TAG}\\n`, ''), '');
    } else {
      if (has) { already++; continue; }
      // An existing robots meta would conflict — replace it rather than stack.
      if (/<meta[^>]+name=["']robots["']/i.test(text)) {
        out = text.replace(/([ \t]*)<meta[^>]+name=["']robots["'][^>]*>/i,
          `$1${MARKER}\n$1${TAG}`);
      } else {
        // Insert directly after the viewport meta, matching the convention
        // used by travel/*/planner.html.
        out = text.replace(/([ \t]*)(<meta[^>]+name=["']viewport["'][^>]*>)/i,
          `$1$2\n$1${MARKER}\n$1${TAG}`);
      }
      if (out === text) { console.error(`  FAILED to place tag in ${rel}`); continue; }
    }

    if (out === text) continue;
    if (CHECK) { drift++; console.log(`  DRIFT ${rel}`); continue; }
    writeLF(abs, out, crlf);
    changed++;
    console.log(`  ${LIFT ? 'lifted' : 'noindexed'} ${rel}`);
  }
}

if (CHECK) {
  if (drift) console.log(`${drift} files need the noindex tag`);
  else if (skipped) console.log(`no drift — ${skipped} locale(s) below the noindex gate`);
  else console.log('all target pages carry the tag');
  process.exit(drift ? 1 : 0);
}
console.log(`${changed} changed, ${already} already tagged, ${skipped} locale(s) skipped as translated`);
console.log('Now rerun: node scripts/gen-sitemap.cjs   (it drops noindex pages)');
